/// Câte povești sunt gratuite (primele din listă). Restul se deblochează
/// printr-o singură plată — vezi `services/unlock_service.dart`.
const int kFreeStoryCount = 7;

final Set<String> _freeStoryIds =
    allStories.take(kFreeStoryCount).map((s) => s.id).toSet();

/// True dacă povestea face parte din cele gratuite.
bool isFreeStory(Story story) => _freeStoryIds.contains(story.id);

